import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db_connection():
    return psycopg2.connect(
        host=DB_HOST,
        database=DB_NAME,
        user=DB_USER,
        password=DB_PASS
    )

def verify_session(token):
    """Verify session token using HMAC - prevents session forgery"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 2:
        return None
    payload, sig = parts
    secret = os.environ.get('SESSION_SECRET', 'dev-key')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    # Session verification
    session = verify_session(auth[7:])
    if not session:
        return jsonify({'error': 'invalid session'}), 403

    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build query with filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    base_query = "SELECT id, username, email, department, role FROM users"
    if conditions:
        base_query += " WHERE " + " AND ".join(conditions)
    base_query += " LIMIT 50"

    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute(base_query)
        rows = cur.fetchall()
        cur.close()
        conn.close()

        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        return jsonify({'users': results})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/<int:user_id>/details', methods=['GET'])
def user_details(user_id):
    """Get detailed user info by ID - uses parameterized query"""
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute("SELECT * FROM users WHERE id = %s", (user_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'user': {'id': row[0], 'username': row[1]}})
        return jsonify({'error': 'not found'}), 404
    except Exception as e:
        return jsonify({'error': 'internal error'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
